import{_ as s,o as a,c as i,a2 as t}from"./chunks/framework.CQxpk36T.js";const u=JSON.parse('{"title":"Héberger sur un serveur","description":"","frontmatter":{},"headers":[],"relativePath":"hebergement.md","filePath":"hebergement.md","lastUpdated":1793563901000}'),n={name:"hebergement.md"};function l(r,e,o,p,h,c){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="heberger-sur-un-serveur" tabindex="-1">Héberger sur un serveur <a class="header-anchor" href="#heberger-sur-un-serveur" aria-label="Permalink to &quot;Héberger sur un serveur&quot;">​</a></h1><p><code>npm run dev</code> suffit pour décrire sa propriété. Pour l&#39;avoir tous les jours sur le téléphone, HAven se construit en quelques fichiers statiques, servis par un petit serveur web sur une machine de la maison (le serveur de Home Assistant, un NAS, un mini-PC).</p><h2 id="avec-docker" tabindex="-1">Avec Docker <a class="header-anchor" href="#avec-docker" aria-label="Permalink to &quot;Avec Docker&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span></span></code></pre></div><ol><li>Construit l&#39;application dans <code>dist/</code>, avec la propriété choisie dans <code>.env.local</code> ;</li><li>lance le conteneur <code>maison-3d</code> (<code>deploy/docker-compose.yml</code>) : un <a href="https://caddyserver.com" target="_blank" rel="noreferrer">Caddy</a> qui sert <code>dist/</code> sur <strong><code>127.0.0.1:8099</code></strong>.</li></ol><p>À chaque modification de la propriété (ou après avoir déposé un <code>retouches.json</code>), relancez <code>npm run deploy</code>. Le conteneur redémarre seul avec la machine.</p><div class="info custom-block"><p class="custom-block-title">Pourquoi 127.0.0.1</p><p>Le conteneur n&#39;écoute que sur la machine elle-même : rien n&#39;est exposé sur le réseau tant que vous ne le décidez pas. Tailscale (ci-dessous) le publie sur votre réseau privé.</p></div><p>Caddy est réglé pour que les mises à jour se voient aussitôt : les fichiers versionnés (<code>/assets/…</code>) sont gardés un an par le navigateur, la page et le cache hors ligne sont toujours revalidés.</p><h2 id="sans-docker" tabindex="-1">Sans Docker <a class="header-anchor" href="#sans-docker" aria-label="Permalink to &quot;Sans Docker&quot;">​</a></h2><p><code>dist/</code> est un site statique : n&#39;importe quel serveur web convient (nginx, Apache, le dossier <code>www</code> de Home Assistant…). Il suffit de renvoyer <code>index.html</code> pour les adresses inconnues.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # puis servez dist/</span></span></code></pre></div><h2 id="depuis-le-telephone-avec-tailscale" tabindex="-1">Depuis le téléphone, avec Tailscale <a class="header-anchor" href="#depuis-le-telephone-avec-tailscale" aria-label="Permalink to &quot;Depuis le téléphone, avec Tailscale&quot;">​</a></h2><p>Pour y accéder de partout sans rien ouvrir sur Internet, le plus simple est <a href="https://tailscale.com" target="_blank" rel="noreferrer">Tailscale</a>, un réseau privé entre vos appareils :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tailscale</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --http=80</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8099</span></span></code></pre></div><p>Puis <code>http://&lt;nom de la machine&gt;</code> sur le téléphone, Tailscale actif. Sur iPhone : Partager → « Sur l&#39;écran d&#39;accueil » l&#39;installe en plein écran.</p><h2 id="https" tabindex="-1">HTTPS <a class="header-anchor" href="#https" aria-label="Permalink to &quot;HTTPS&quot;">​</a></h2><p>Pour l&#39;<strong>ouverture instantanée hors ligne</strong> (le cache de l&#39;application), les navigateurs exigent HTTPS. Avec Tailscale : activez « HTTPS Certificates » dans la console Tailscale (rubrique DNS), puis :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tailscale</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --http=80</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> off</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tailscale</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --https=443</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8099</span></span></code></pre></div><p>L&#39;adresse devient <code>https://&lt;nom de la machine&gt;.&lt;votre tailnet&gt;.ts.net</code>.</p><div class="warning custom-block"><p class="custom-block-title">Home Assistant aussi</p><p>Une page en HTTPS ne peut pas parler à un Home Assistant en HTTP. Servez Home Assistant en HTTPS de la même façon (<code>tailscale serve</code> sur le port 8123, par exemple), et utilisez cette adresse dans les réglages de HAven. Voir <a href="/HAven-docs/home-assistant/#http-ou-https">Se connecter</a>.</p></div><h2 id="une-tablette-murale" tabindex="-1">Une tablette murale <a class="header-anchor" href="#une-tablette-murale" aria-label="Permalink to &quot;Une tablette murale&quot;">​</a></h2><ul><li>Installez HAven sur l&#39;écran d&#39;accueil pour le plein écran ;</li><li>connectez-le avec un compte Home Assistant dédié ;</li><li>choisissez la qualité graphique <strong>Économe</strong> si la tablette chauffe ;</li><li>l&#39;interface s&#39;assombrit seule la nuit.</li></ul><h2 id="mettre-a-jour-haven" tabindex="-1">Mettre à jour HAven <a class="header-anchor" href="#mettre-a-jour-haven" aria-label="Permalink to &quot;Mettre à jour HAven&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span></span></code></pre></div><p>Votre dossier de propriété n&#39;est pas touché : il est hors de git.</p>`,25)])])}const k=s(n,[["render",l]]);export{u as __pageData,k as default};
